function [ok] = rotor_fits(u, k, selectable)
%ROTOR_FITS  Whether a catalogue model of kind k may serve use u: a selectable model (its datasheet states momentum, torque, mass
%   and steady power), a wheel for wheels, a CMG or a CMG cluster for CMGs and VSCMGs.
%   u: RotorUse (passed a choice, as its option's number)
%   k: CatalogueKind (passed a choice, as its option's number)
%   selectable: bool (passed true or false)
%   returns ok: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    ok = false;
    if (u == 0)
        ok = (selectable && (k == 0));
    else
        ok = (selectable && ((k == 1) || (k == 2)));
    end
end
